import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown, typeSearch } from '../_lib/app-0710.ts';
import { catalogTitles, HISTORY_TITLE } from '../_lib/app-2110.ts';
import { goHome, nodes, openCatalog, searchCatalog, catalogCard, buttonStartsWith, openZmanim, counter } from '../_lib/readiness-1910.ts';
import { saveShot, openTehilimScreen, segment } from '../_lib/app-2510.ts';

const KL_OK = 'תהילים ק״ל';
const KL_BAD = 'תהילים קל';
const YAALE = 'יעלה ויבוא';
const YAALE_BAD = 'ויבא';                       // без огласовок: в тексте с ניקוד («וְיָבֹא») подстрока не совпадёт
const HISTORY_OLD = 'היסטוריית תפילות שלי';
const T39_TITLE = 'תהילים ל״ט';
const T39_NAME = 'למנצח לידותון מזמור';
const T39_BAD = 'לידיתון';
const APPROVED_BY = 'אושר על ידי מנהל תוכן';

/** Номер дафа: одна буква — «X׳», несколько — «XY״Z» (ט״ו/ט״ז тоже подходят). */
const DAF_NUM_OK = /^([א-ת]׳|[א-ת]{1,3}״[א-ת])$/;
/** «<מסכת> דף <номер>» в подписи (номер — до пробела/запятой/конца; «דף יומי …» — заголовок строки, не значение). */
const DAF_VALUE = /(?:^|\s)דף\s+(?!יומי)([^\s,.:;—–-]+)/g;

async function waitNodes(where: string, cond: (labels: string[]) => boolean, timeout = 20000) {
  let labels: string[] = [];
  await driver.waitUntil(async () => { labels = (await nodes()).map((n) => n.label); return cond(labels); },
    { timeout, interval: 700, timeoutMsg: `${where}: не дождались (на экране: ${labels.slice(0, 40).join(' | ')})` });
  return labels;
}

describe('25.10 — написание названий (#7580ef)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('SP-01a «תפילות» → каталог: «תהילים ק״ל», нет «תהילים קל» #7580ef #56d002bd F-94 AC4 @prod-safe', async () => {
    await openCatalog();
    await searchCatalog('תהילים');
    await expect(catalogCard(KL_OK)).toBeExisting({ wait: 15000 });
    const titles = await catalogTitles();
    console.log(`[SP-01a] каталог «תהילים»: ${titles.join(' | ')}`);
    expect(titles).toContain(KL_OK);
    expect(titles).not.toContain(KL_BAD);
    expect(await catalogCard(KL_BAD).isExisting().catch(() => false)).toBe(false);
    await saveShot('SP-01a-tehilim-kl.png');
    await searchCatalog('');
  });

  it('SP-01b «זמני התפילות של היום» → «דף יומי בבלי» и «דף יומי ירושלמי»: номер дафа с ׳ или ״ (25.10: «בכורות דף ל״ז», «סנהדרין דף ו׳») #7580ef #56d002bd F-94 AC4 @prod-safe', async () => {
    await openZmanim();                                    // headerTap('זמני התפילות של היום') — только по имени
    await scrollToText('דף יומי בבלי');
    await scrollToText('דף יומי ירושלמי');
    const values: string[] = [];
    const labels = await waitNodes('לימוד יומי', (ls) => {
      values.length = 0;
      for (const l of ls) for (const m of l.matchAll(DAF_VALUE)) values.push(`${l.trim()} ⇒ ${m[1]}`);
      return values.length >= 2;                            // бавли + ирушалми
    });
    expect(labels.some((l) => l.includes('דף יומי בבלי'))).toBe(true);
    expect(labels.some((l) => l.includes('דף יומי ירושלמי'))).toBe(true);
    console.log(`[SP-01b] ${values.join(' | ')}`);
    const bad = values.filter((v) => !DAF_NUM_OK.test(v.split(' ⇒ ')[1]));
    expect(bad).toEqual([]);
    await saveShot('SP-01b-daf-yomi.png');
  });

  it('SP-01c «תפילות» → «יעלה ויבוא» → «פתיחת יעלה ויבוא, נוסח התפילה …»: метка קטע «יעלה ויבוא», в каталоге так же; «ויבא» нет ни в одном названии #7580ef #56d002bd D-33 @prod-safe', async () => {
    await openCatalog();
    await searchCatalog(YAALE);
    const card = catalogCard(YAALE);
    await expect(card).toBeExisting({ wait: 15000 });
    const titles = await catalogTitles();
    expect(titles).toContain(YAALE);
    expect(titles.filter((t) => t.includes(YAALE_BAD))).toEqual([]);
    await card.click();
    // 25.10: «פתיחת יעלה ויבוא, נוסח התפילה אשכנזי» (нусах аккаунта; у ספרד — свой хвост).
    const open = buttonStartsWith(`פתיחת ${YAALE}, נוסח התפילה`);
    await expect(open).toBeExisting({ wait: 8000 });
    console.log(`[SP-01c] ${await open.getAttribute(driver.isAndroid ? 'content-desc' : 'label').catch(() => '')}`);
    await open.click();
    // Метка קטע — отдельный узел с точным текстом «יעלה ויבוא» (заголовок экрана — «יעלה ויבוא (<נוסח>)»).
    const labels = await waitNodes('экран «יעלה ויבוא»', (ls) => ls.some((l) => l.trim() === YAALE));
    const badTitles = labels.filter((l) => l.includes(YAALE_BAD));   // с ניקוד («וְיָבֹא») сюда не попадает
    expect(badTitles).toEqual([]);
    await saveShot('SP-01c-yaale-veyavo.png');
  });

  it('SP-01d Главная (4+ молитв) → «צפה בהכל» → заголовок «היסטוריית התפילות שלי» (не «היסטוריית תפילות שלי») #7580ef #56d002bd S-26 @prod-safe', async function () {
    await goHome();
    const total = await counter('סה״כ תפילות');
    if (total < 4) skipWith(this, `у аккаунта ${total} молитв — «צפה בהכל» показывается только при 4+ (F-104 AC3); проверить на аккаунте с историей`);
    await (await scrollToText('צפה בהכל')).click();
    await expect(byText(HISTORY_TITLE)).toBeDisplayed({ wait: 20000 });
    expect(await shown(byText(HISTORY_OLD))).toBe(false);
    await saveShot('SP-01d-history-title.png');
  });

  it('SP-01e «ברכות» → «תהילים» → поиск «39» → «תהילים ל״ט — למנצח לידותון מזמור» → глава: «תהילים ל״ט» + «למנצח לידותון מזמור», без «לידיתון» и скобок, «אושר על ידי מנהל תוכן» #7580ef #56d002bd S-24 AC5 @prod-safe', async () => {
    await openTehilimScreen();                             // после #8060ad — под вкладкой «ברכות» (запасной путь «תהילים»)
    await segment('תהילים');
    await typeSearch('39');
    if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
    // Список: подпись главы с новым именем; старого и скобок нет.
    const list = await waitNodes('список «39»', (ls) => ls.some((l) => l.includes(T39_NAME)));
    const row = list.filter((l) => l.includes(T39_NAME));
    console.log(`[SP-01e] список: ${row.join(' | ')}`);
    expect(list.filter((l) => l.includes(T39_BAD))).toEqual([]);
    expect(row.filter((l) => /[[\]()]/.test(l))).toEqual([]);
    await saveShot('SP-01e-t39-list.png');
    // Открыть главу: кнопка «תהילים ל״ט — …», запасной путь — текст «ל״ט».
    const item = byLabelStartsWith(`${T39_TITLE} —`);
    if (await item.isExisting().catch(() => false)) await item.click();
    else await (await byText('ל״ט')).click();
    await expect(byText(T39_TITLE)).toBeDisplayed({ wait: 20000 });
    const chapter = await waitNodes('глава ל״ט', (ls) => ls.some((l) => l.includes(T39_NAME)));
    expect(chapter.filter((l) => l.includes(T39_BAD) || l.includes('[לידותון]'))).toEqual([]);
    expect(chapter.filter((l) => l.includes(T39_NAME) && /[[\]()]/.test(l))).toEqual([]);
    await scrollToText('אושר על ידי');
    await expect(byTextContains(APPROVED_BY)).toBeExisting({ wait: 10000 });
    await saveShot('SP-01e-t39-chapter.png');
  });
});
